use futures::StreamExt;
use rig::agent::MultiTurnStreamItem;
use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};


#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
        .preamble("You are a helpful assistant.")
        .build();


    // Await the runner: run the loop to completion and get a `PromptResponse`.
    let response = agent
        .prompt("Find the answer and show your work.")
        .max_turns(5)
        .await?;


    println!("answer: {}", response.output());
    println!("model calls: {}", response.completion_calls.len());
    println!("tokens: {:?}", response.usage.total_tokens);


    // Or stream the same run: deltas and tool activity, then the final response.
    let mut stream = agent.prompt("Now explain it to a child.").max_turns(5).stream();
    while let Some(item) = stream.next().await {
        if let MultiTurnStreamItem::FinalResponse(done) = item? {
            println!("\n{}", done.output());
        }
    }


    Ok(())
}

use rig::{AgentBuilder, completion::PromptError};
use rig::memory::MemoryStore;
use rig::providers::openai::{self, OpenAI};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
        .memory(MemoryStore::default()).build();
    match agent.prompt("What did I ask earlier?").conversation("user-42").await {
        Ok(response) => println!("{}", response.output()),
        Err(error) => {
            if let PromptError::Memory { error: store_error, response } = &error {
                eprintln!("conversation persistence failed: {store_error}");
                if let Some(finished) = response {
                    eprintln!("finished answer (save not confirmed): {}", finished.output());
                    // Recover/reconcile persistence; do not repeat a tool-using run blindly.
                } else {
                    eprintln!("history could not be loaded; the model was not called");
                }
            }
            return Err(error.into());
        }
    }
    Ok(())
}

use rig::tool::ToolContext;


#[derive(serde::Serialize, serde::Deserialize, rig::ContextValue)]
#[context(key = "tenant_id")]
struct TenantId(String);


let mut context = ToolContext::new();
context.insert(TenantId("acme".into()))?;


let response = agent
    .prompt("Update my account preferences.")
    .tool_context(context)
    .await?;
